/**
 * What `theme-preference.tsx` (device) and `theme-preference.web.tsx` (the web, Expo's and the
 * DOM's) share: the preference's type, where it is stored, and the pre-paint script.
 *
 * A separate module for the usual reason: Metro resolves `./theme-preference` to the `.web.tsx`
 * on web, so the web file cannot import shared pieces from it without importing itself.
 */

/** Which palette to paint. `system` follows the device and is what nothing stored means. */
export type ThemePreference = "light" | "dark" | "system";

/** In the order a picker shows them. */
export const THEME_PREFERENCES: readonly ThemePreference[] = ["light", "dark", "system"];

/**
 * The key the preference is stored under, on both platforms. One key rather than an option: the
 * picker's own hook, the one at the app's root and the pre-paint script all have to agree on it,
 * and a key passed to one of them and not the others is a picker that writes where nothing reads.
 */
export const THEME_STORAGE_KEY = "cubeui-theme";

export function isThemePreference(value: unknown): value is ThemePreference {
  return value === "light" || value === "dark" || value === "system";
}

/**
 * Where the device keeps the preference. `@react-native-async-storage/async-storage` fits as it
 * is; `expo-secure-store` or MMKV fit behind two lambdas. The item takes the shape rather than a
 * package, so it adds no storage dependency to an app that already has one. Either method may
 * return a promise.
 */
export type ThemeStorage = {
  getItem: (key: string) => string | null | undefined | Promise<string | null | undefined>;
  setItem: (key: string, value: string) => void | Promise<void>;
};

export type ThemePreferenceOptions = {
  /**
   * Device only: where the choice persists between launches. Without one, a choice lasts until
   * the app is closed. Pass it where the app starts; a `useThemePreference()` anywhere else — the
   * one inside `ThemePicker` — writes through it too. The web always uses `localStorage`, because
   * it is the one store the pre-paint script can read before any of the bundle has loaded.
   */
  storage?: ThemeStorage | undefined;
};

/** What `useThemePreference` returns: the stored choice and the one way to change it. */
export type ThemePreferenceState = readonly [
  preference: ThemePreference,
  setPreference: (next: ThemePreference) => void,
];

/**
 * The web's first paint, before React mounts: the same rule `useThemePreference` applies, as a
 * self-contained script for an inline `<script>` in the page's `<head>`. Render it with
 * `dangerouslySetInnerHTML` where the head is React (Expo's `+html.tsx`, a Next layout); paste the
 * copy in the skill's `controls.md` where it is a static `index.html`. A unit test holds that copy
 * to this string.
 *
 * `dark` goes on `<html>` for Dark, and for System while the device is dark; `light` goes on it for
 * Light only. `dist/tokens.native.css` (Expo web) reads both over its `prefers-color-scheme` block;
 * `tokens.web.css` (the DOM registry) has no media query and reads `.dark` alone, which is why
 * System still sets `dark` on a dark device rather than leaving it to a query that stylesheet does
 * not have.
 *
 * Written in ES5 and wrapped in `try`, because it runs before anything else on the page and a
 * browser with storage switched off throws on `localStorage` itself.
 */
export const THEME_PRE_PAINT_SCRIPT =
  "(function(){try{" +
  `var p=localStorage.getItem(${JSON.stringify(THEME_STORAGE_KEY)});` +
  'var d=p==="dark"||(p!=="light"&&matchMedia("(prefers-color-scheme: dark)").matches);' +
  'var c=document.documentElement.classList;c.toggle("dark",d);c.toggle("light",p==="light")' +
  "}catch(e){}})();";

/**
 * Copied from `registry/ui/theme-preference.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The theme preference on the web — an Expo app's web build, where Metro picks this file over
 * `theme-preference.tsx`, and a DOM app, where it is the whole item. `theme-preference-base.ts`
 * holds what the two halves share.
 *
 * `localStorage` is the store, and the source of truth: the hook reads it through
 * `useSyncExternalStore`, so two components calling the hook, or two tabs, cannot disagree.
 * Applying the choice is a class on `<html>` — see `THEME_PRE_PAINT_SCRIPT` for the rule and why
 * System still sets `dark` on a dark device.
 *
 * Nothing touches `window` at import, and the server snapshot is `system`, so a server render
 * paints what the pre-paint script is about to correct rather than throwing.
 */

import { useEffect, useSyncExternalStore } from "react";
import {
  isThemePreference,
  THEME_STORAGE_KEY,
  type ThemePreference,
  type ThemePreferenceOptions,
  type ThemePreferenceState,
} from "@/components/ui/theme-preference-base";

const DARK_QUERY = "(prefers-color-scheme: dark)";

/** Every hook on the page, told when one of them writes. `storage` events only reach other tabs. */
const listeners = new Set<() => void>();

/** The choice when storage refused it, so a click still sticks for the life of the page. */
let unsaved: ThemePreference | null = null;

function read(): ThemePreference {
  if (unsaved) return unsaved;
  try {
    const stored = window.localStorage.getItem(THEME_STORAGE_KEY);
    return isThemePreference(stored) ? stored : "system";
  } catch {
    // Storage switched off, or a sandboxed frame: there is nothing to read, which is `system`.
    return "system";
  }
}

function prefersDark() {
  return typeof window.matchMedia === "function" && window.matchMedia(DARK_QUERY).matches;
}

function apply(preference: ThemePreference) {
  const classes = document.documentElement.classList;
  classes.toggle("dark", preference === "dark" || (preference === "system" && prefersDark()));
  classes.toggle("light", preference === "light");
}

function subscribe(onChange: () => void) {
  listeners.add(onChange);
  const onStorage = (event: StorageEvent) => {
    if (event.key === THEME_STORAGE_KEY || event.key === null) onChange();
  };
  window.addEventListener("storage", onStorage);
  return () => {
    listeners.delete(onChange);
    window.removeEventListener("storage", onStorage);
  };
}

/** Module-level, so every caller's setter is the same function and safe in a dependency list. */
function setPreference(next: ThemePreference) {
  try {
    window.localStorage.setItem(THEME_STORAGE_KEY, next);
    unsaved = null;
  } catch {
    // Not persisted, but still applied: the page should not ignore the click.
    unsaved = next;
  }
  apply(next);
  for (const listener of listeners) listener();
}

/**
 * The stored light / dark / system choice, and a setter that stores and applies it. Call it where
 * the app starts, so the choice is applied — and, on System, kept in step with the device — on
 * every screen, not only the one with the picker on it.
 */
export function useThemePreference(_options: ThemePreferenceOptions = {}): ThemePreferenceState {
  const preference = useSyncExternalStore(subscribe, read, () => "system" as const);

  useEffect(() => {
    apply(preference);
    if (preference !== "system" || typeof window.matchMedia !== "function") return;
    // Following the device means repainting when the device changes, without a reload.
    const query = window.matchMedia(DARK_QUERY);
    const onChange = () => apply("system");
    query.addEventListener("change", onChange);
    return () => query.removeEventListener("change", onChange);
  }, [preference]);

  return [preference, setPreference] as const;
}

/**
 * Compiled from `registry/ui/theme-picker.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * The prose below is the source's own, carried across untouched, which is the property that makes
 * a compiled registry worth having: this is the same component, not a second one to keep in step
 * by hand. Where a comment names a React Native component it is describing the source; the
 * element map in `scripts/rn2web/tables.mjs` says what that became here.
 */

/**
 * Light, Dark and System as three tiles — a `RadioGroup variant="card"`, so one tab stop and arrow
 * keys that move and choose come with it. One source for both platforms, compiled to the web item.
 *
 * Every app wrote this, and wrote the storage and the `<html>` class beside it: the control is the
 * small part. So by default the picker is **bound** — it reads and writes `useThemePreference()`,
 * which stores the choice and applies it, and there is nothing to wire. Pass `value` and it is
 * **controlled** instead: it only reports the choice through `onValueChange`, for an app that keeps
 * the preference somewhere of its own (on the account, in a settings form), and the hook is not
 * called at all, so nothing here paints over the app's own choice.
 */

import { isThemePreference, type ThemePreference } from "@/components/ui/theme-preference-base";
import { Monitor, Moon, Sun } from "@/components/ui/icons";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useThemePreference } from "@/components/ui/theme-preference";

type ThemePickerProps = {
  /** The checked choice, for a controlled picker. Left out, the picker is bound to the hook. */
  value?: ThemePreference | undefined;
  /** Told of every choice — the only way a controlled picker changes; a bound one also stores it. */
  onValueChange?: ((value: ThemePreference) => void) | undefined;
  disabled?: boolean | undefined;
  id?: string | undefined;
  className?: string | undefined;
  /** The group's name. Defaults to "Theme"; pass `aria-labelledby` instead when a heading names it. */
  "aria-label"?: string | undefined;
  "aria-labelledby"?: string | undefined;
  "aria-describedby"?: string | undefined;
};

function ThemeOptions({
  value,
  onValueChange,
  disabled,
  id,
  className,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  "aria-describedby": ariaDescribedBy,
}: ThemePickerProps) {
  return (
    <RadioGroup
      variant="card"
      value={value}
      onValueChange={(next) => {
        if (isThemePreference(next)) onValueChange?.(next);
      }}
      disabled={disabled}
      id={id}
      className={className}
      aria-label={ariaLabelledBy ? undefined : (ariaLabel ?? "Theme")}
      aria-labelledby={ariaLabelledBy}
      aria-describedby={ariaDescribedBy}
    >
      <RadioGroupItem
        value="light"
        label="Light"
        hint="Always light"
        icon={<Sun className="h-5 w-5" />}
      />
      <RadioGroupItem
        value="dark"
        label="Dark"
        hint="Always dark"
        icon={<Moon className="h-5 w-5" />}
      />
      <RadioGroupItem
        value="system"
        label="System"
        hint="Follow the device"
        icon={<Monitor className="h-5 w-5" />}
      />
    </RadioGroup>
  );
}

function BoundThemePicker({ onValueChange, ...props }: ThemePickerProps) {
  const [preference, setPreference] = useThemePreference();
  return (
    <ThemeOptions
      {...props}
      value={preference}
      onValueChange={(next) => {
        setPreference(next);
        onValueChange?.(next);
      }}
    />
  );
}

function ThemePicker(props: ThemePickerProps) {
  return props.value === undefined ? <BoundThemePicker {...props} /> : <ThemeOptions {...props} />;
}

export type { ThemePickerProps };
export { ThemePicker };
